cd /output/yaml && node -e '
const fs = require("fs");
let s = fs.readFileSync("errors.mjs", "utf8");
const re = /const isBreak = \(ch\) =>\n[^;]*;/;
const rep = "const isBreak = (ch) =>\n      ch === \x27\\0\x27 || ch === \x27\\r\x27 || ch === \x27\\n\x27 || ch === \x27\\x85\x27 ||\n      ch === \x27\\u2028\x27 || ch === \x27\\u2029\x27 || ch === undefined;";
if (!re.test(s)) { console.error("pattern not found"); process.exit(1); }
s = s.replace(re, rep);
fs.writeFileSync("errors.mjs", s);
console.log("fixed");
'

cd /output/yaml && node -e 'const m = await import("./errors.mjs"); const mk = new m.Mark("line1\nfoo: bar\n", 8, 1, 2); console.log(String(mk));' --input-type=module 2>/dev/null || node --experimental-vm-modules -e '' ; node -e '
import("./errors.mjs").then(m => {
  const mk = new m.Mark("line1\nfoo: bar\n", 8, 1, 2);
  console.log(String(mk));
  console.log(new m.ScannerError("while scanning", mk, "bad char", mk).message);
});'

