// YAML tokenizer: a faithful port of PyYAML's scanner.py (pure-Python
// version) to JavaScript. It produces the same token stream, including
// PyYAML's simple-key machinery, indentation tracking, flow scalars with
// escape processing, and block scalars with chomping/indent indicators.

import { Mark, ReaderError, ScannerError } from './errors.mjs';

// Line break characters recognized by the scanner.
const BREAKS = '\0\r\n  ';
// Characters that may follow indicators such as '-', '?', ':' in block
// context (space, tab, line breaks, end of stream).
const BLANK_OR_BREAK = '\0 \t\r\n  ';

function isBreak(ch) {
  return ch === '\r' || ch === '\n' || ch === '' || ch === ' ' || ch === ' ';
}

function isBlankOrBreak(ch) {
  return ch === '\0' || ch === ' ' || ch === '\t' || isBreak(ch);
}

function isAlphaNum(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') ||
    (ch >= 'A' && ch <= 'Z') || ch === '-' || ch === '_';
}

// Characters allowed in a tag URI (PyYAML's scan_tag_uri set).
const URI_CHARS = "-;/?:@&=+$,_.!~*'()[]%";

// Escape replacements for double-quoted scalars (PyYAML ESCAPE_REPLACEMENTS).
const ESCAPE_REPLACEMENTS = {
  '0': '\0',
  'a': '',
  'b': ' ',
  't': '	',
  '\t': '	',
  'n': '\n',
  'v': '',
  'f': ' ',
  'r': '',
  'e': '',
  ' ': ' ',
  '"': '"',
  '\\': '\\',
  '/': '/',
  'N': '',
  '_': ' ',
  'L': ' ',
  'P': ' ',
};

// Escape codes introducing hex sequences (PyYAML ESCAPE_CODES).
const ESCAPE_CODES = { x: 2, u: 4, U: 8 };

// A possible simple key position (PyYAML's SimpleKey namedtuple).
class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

// Tokens are plain objects: { type, id, startMark, endMark, ...payload }.
// `id` mirrors PyYAML's token ids for error messages.
function makeToken(type, id, startMark, endMark, extra) {
  return Object.assign({ type, id, startMark, endMark }, extra);
}

// PyYAML Reader.NON_PRINTABLE as a JS regex.
// eslint-disable-next-line no-control-regex
const NON_PRINTABLE = /[^\x09\x0A\x0D\x20-\x7E\x85 -퟿-�]/;

export class Scanner {
  constructor(src) {
    this.src = String(src);
    this.index = 0;
    this.line = 0;
    this.column = 0;
    this.checkPrintable();

    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();

    // Scan the whole stream eagerly; the scanner is self-contained so this
    // is equivalent to PyYAML's lazy scanning.
    this.fetchStreamStart();
    while (!this.done) {
      this.fetchMoreTokens();
    }
  }

  checkPrintable() {
    const m = NON_PRINTABLE.exec(this.src);
    if (m) {
      throw new ReaderError(m.index, m[0], 'special characters are not allowed');
    }
  }

  // ------------------------------------------------------------------
  // Reader interface
  // ------------------------------------------------------------------

  peek(offset = 0) {
    const i = this.index + offset;
    return i < this.src.length ? this.src[i] : '\0';
  }

  prefix(length) {
    return this.src.slice(this.index, this.index + length);
  }

  forward(length = 1) {
    while (length > 0 && this.index < this.src.length) {
      const ch = this.src[this.index];
      this.index += 1;
      if (ch === '\n' || ch === '' || ch === ' ' || ch === ' ' ||
          (ch === '\r' && this.src[this.index] !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      length -= 1;
    }
  }

  getMark() {
    return new Mark(this.src, this.index, this.line, this.column);
  }

  // ------------------------------------------------------------------
  // Token queue
  // ------------------------------------------------------------------

  // ------------------------------------------------------------------
  // Simple keys
  // ------------------------------------------------------------------

  removePossibleSimpleKey() {
    const key = this.possibleSimpleKeys.get(this.flowLevel);
    if (key !== undefined) {
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  savePossibleSimpleKey() {
    // The next token may start a simple key. Called for ALIAS, ANCHOR, TAG,
    // SCALAR(flow), '[', and '{'.
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const required = (this.flowLevel === 0 && this.indent === this.column);
      this.possibleSimpleKeys.set(this.flowLevel, new SimpleKey(
        this.tokensTaken + this.tokens.length, required,
        this.index, this.line, this.column, this.getMark()));
    }
  }

  stalePossibleSimpleKeys() {
    // Simple keys are limited to a single line and 1024 characters.
    for (const [level, key] of [...this.possibleSimpleKeys]) {
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  // ------------------------------------------------------------------
  // Indentation
  // ------------------------------------------------------------------

  unwindIndent(column) {
    // In flow context indentation is ignored.
    if (this.flowLevel !== 0) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(makeToken('block-end', '<block end>', mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // ------------------------------------------------------------------
  // Token fetchers
  // ------------------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(makeToken('stream-start', '<stream start>', mark, mark));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys.clear();
    const mark = this.getMark();
    this.tokens.push(makeToken('stream-end', '<stream end>', mark, mark));
    this.done = true;
  }

  fetchMoreTokens() {
    // Eat whitespace and comments until the next token.
    this.scanToNextToken();
    // Remove obsolete possible simple keys.
    this.stalePossibleSimpleKeys();
    // Compare the current indentation and column.
    this.unwindIndent(this.column);

    const ch = this.peek();
    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && this.flowLevel === 0) return this.fetchLiteral();
    if (ch === '>' && this.flowLevel === 0) return this.fetchFolded();
    if (ch === '\'') return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    return this.fetchPlain();
  }

  checkDirective() {
    // DIRECTIVE: ^ '%'
    return this.column === 0;
  }

  checkDocumentStart() {
    // DOCUMENT-START: ^ '---' (' '|'\n')
    if (this.column === 0) {
      if (this.prefix(3) === '---' && isBlankOrBreak(this.peek(3))) {
        return true;
      }
    }
    return false;
  }

  checkDocumentEnd() {
    // DOCUMENT-END: ^ '...' (' '|'\n')
    if (this.column === 0) {
      if (this.prefix(3) === '...' && isBlankOrBreak(this.peek(3))) {
        return true;
      }
    }
    return false;
  }

  checkBlockEntry() {
    // BLOCK-ENTRY: '-' (' '|'\n')
    return isBlankOrBreak(this.peek(1));
  }

  checkKey() {
    // KEY(flow context): '?'
    if (this.flowLevel !== 0) return true;
    // KEY(block context): '?' (' '|'\n')
    return isBlankOrBreak(this.peek(1));
  }

  checkValue() {
    // VALUE(flow context): ':'
    if (this.flowLevel !== 0) return true;
    // VALUE(block context): ':' (' '|'\n')
    return isBlankOrBreak(this.peek(1));
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const token = this.scanDirective();
    this.tokens.push(token);
  }

  fetchDocumentStart() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(makeToken('document-start', '<document start>', startMark, endMark));
  }

  fetchDocumentEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(makeToken('document-end', '<document end>', startMark, endMark));
  }

  fetchFlowSequenceStart() {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('flow-sequence-start', '[', startMark, endMark));
  }

  fetchFlowMappingStart() {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('flow-mapping-start', '{', startMark, endMark));
  }

  fetchFlowSequenceEnd() {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('flow-sequence-end', ']', startMark, endMark));
  }

  fetchFlowMappingEnd() {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('flow-mapping-end', '}', startMark, endMark));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('flow-entry', ',', startMark, endMark));
  }

  fetchBlockEntry() {
    const startMark = this.getMark();
    if (this.flowLevel === 0) {
      // Are we allowed to start a new entry?
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'sequence entries are not allowed here', startMark);
      }
      // We may need to add BLOCK-SEQUENCE-START.
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(makeToken('block-sequence-start', '<block sequence start>', mark, mark));
      }
    }
    // It's an error for the block entry to occur in the flow context, but we
    // let the parser detect this.
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('block-entry', '-', startMark, endMark));
  }

  fetchKey() {
    const startMark = this.getMark();
    if (this.flowLevel === 0) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'mapping keys are not allowed here', startMark);
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(makeToken('block-mapping-start', '<block mapping start>', mark, mark));
      }
    }
    // Simple keys are allowed after '?' in the block context.
    this.allowSimpleKey = this.flowLevel === 0;
    this.removePossibleSimpleKey();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('key', '?', startMark, endMark));
  }

  fetchValue() {
    const simpleKey = this.possibleSimpleKeys.get(this.flowLevel);
    if (simpleKey !== undefined) {
      this.possibleSimpleKeys.delete(this.flowLevel);
      // Create a KEY token and insert it into the queue.
      this.tokens.splice(simpleKey.tokenNumber - this.tokensTaken, 0,
        makeToken('key', '?', simpleKey.mark, simpleKey.mark));
      // If this key starts a new block mapping, add BLOCK-MAPPING-START.
      if (this.flowLevel === 0) {
        if (this.addIndent(simpleKey.column)) {
          this.tokens.splice(simpleKey.tokenNumber - this.tokensTaken, 0,
            makeToken('block-mapping-start', '<block mapping start>', simpleKey.mark, simpleKey.mark));
        }
      }
      // There cannot be two simple keys one after another.
      this.allowSimpleKey = false;
    } else {
      // The ':' indicator follows a complex key.
      if (this.flowLevel === 0) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null,
            'mapping values are not allowed here', this.getMark());
        }
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(makeToken('block-mapping-start', '<block mapping start>', mark, mark));
        }
      }
      // Simple keys are allowed after ':' in the block context.
      this.allowSimpleKey = this.flowLevel === 0;
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(makeToken('value', ':', startMark, endMark));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    const token = this.scanAnchor('alias');
    this.tokens.push(token);
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    const token = this.scanAnchor('anchor');
    this.tokens.push(token);
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    const token = this.scanTag();
    this.tokens.push(token);
  }

  fetchLiteral() {
    this.fetchBlockScalar('|');
  }

  fetchFolded() {
    this.fetchBlockScalar('>');
  }

  fetchBlockScalar(style) {
    // A simple key may follow a block scalar.
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const token = this.scanBlockScalar(style);
    this.tokens.push(token);
  }

  fetchSingle() {
    this.fetchFlowScalar('\'');
  }

  fetchDouble() {
    this.fetchFlowScalar('"');
  }

  fetchFlowScalar(style) {
    // A flow scalar could be a simple key.
    this.savePossibleSimpleKey();
    // A simple key cannot follow a flow scalar.
    this.allowSimpleKey = false;
    const token = this.scanFlowScalar(style);
    this.tokens.push(token);
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    // A simple key cannot follow a plain scalar... wait, it can, but the
    // scalar consumes until the line break; simple key is handled by ':'.
    this.allowSimpleKey = false;
    const token = this.scanPlain();
    this.tokens.push(token);
  }

  // ------------------------------------------------------------------
  // Trivia scanning
  // ------------------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === '﻿') {
      this.forward();
    }
    let found = false;
    while (!found) {
      while (this.peek() === ' ') {
        this.forward();
      }
      if (this.peek() === '#') {
        while (!isBreak(this.peek()) && this.peek() !== '\0') {
          this.forward();
        }
      }
      if (this.scanLineBreak()) {
        if (this.flowLevel === 0) {
          this.allowSimpleKey = true;
        }
      } else {
        found = true;
      }
    }
  }

  scanLineBreak() {
    // Transforms:
    //   '\r\n'  -> '\n'
    //   '\r'    -> '\n'
    //   '\n'    -> '\n'
    //   '\x85'  -> '\n'
    //   '\u2028' -> '\u2028'
    //   '\u2029' -> '\u2029'
    //   default -> ''
    const ch = this.peek();
    if (ch === '\r' || ch === '\n' || ch === '') {
      if (this.prefix(2) === '\r\n') {
        this.forward(2);
      } else {
        this.forward();
      }
      return '\n';
    } else if (ch === ' ' || ch === ' ') {
      this.forward();
      return ch;
    }
    return '';
  }

  // ------------------------------------------------------------------
  // Directives
  // ------------------------------------------------------------------

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
    } else {
      // Skip unknown directives.
      while (!isBreak(this.peek()) && this.peek() !== '\0') {
        this.forward();
      }
    }
    const endMark = this.getMark();
    this.scanDirectiveIgnoredLine(startMark);
    return makeToken('directive', '<directive>', startMark, endMark, { name, value });
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNum(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (length === 0) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found '${this.peek()}'`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!isBlankOrBreak(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found '${ch}'`,
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') {
      this.forward();
    }
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or '.', but found '${this.peek()}'`, this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!isBlankOrBreak(this.peek())) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or ' ', but found '${this.peek()}'`, this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!(ch >= '0' && ch <= '9')) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit, but found '${ch}'`, this.getMark());
    }
    let length = 0;
    while (this.peek(length) >= '0' && this.peek(length) <= '9') {
      length += 1;
    }
    const value = parseInt(this.prefix(length), 10);
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') {
      this.forward();
    }
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') {
      this.forward();
    }
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    return this.scanTagHandle('directive', startMark);
  }

  scanTagDirectivePrefix(startMark) {
    return this.scanTagUri('directive', startMark);
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') {
      this.forward();
    }
    if (this.peek() === '#') {
      while (!isBreak(this.peek()) && this.peek() !== '\0') {
        this.forward();
      }
    }
    const ch = this.peek();
    if (!isBreak(ch) && ch !== '\0') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a comment or a line break, but found '${ch}'`, this.getMark());
    }
    this.scanLineBreak();
  }

  // ------------------------------------------------------------------
  // Anchors, aliases, tags
  // ------------------------------------------------------------------

  scanAnchor(kind) {
    const startMark = this.getMark();
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNum(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (length === 0) {
      throw new ScannerError(`while scanning an ${kind}`, startMark,
        `expected alphabetic or numeric character, but found '${this.peek()}'`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!(BLANK_OR_BREAK + '?:,[]{}%@`').includes(ch)) {
      throw new ScannerError(`while scanning an ${kind}`, startMark,
        `expected alphabetic or numeric character, but found '${ch}'`,
        this.getMark());
    }
    const endMark = this.getMark();
    if (kind === 'alias') {
      return makeToken('alias', '<alias>', startMark, endMark, { value });
    }
    return makeToken('anchor', '<anchor>', startMark, endMark, { value });
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle = null;
    let suffix;
    if (ch === '<') {
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while scanning a tag', startMark,
          `expected '>', but found '${this.peek()}'`, this.getMark());
      }
      this.forward();
    } else if (isBlankOrBreak(ch)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!isBreak(ch) && ch !== '\0' && ch !== ' ') {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!(BLANK_OR_BREAK).includes(ch)) {
      throw new ScannerError('while scanning a tag', startMark,
        `expected ' ', but found '${ch}'`, this.getMark());
    }
    const endMark = this.getMark();
    return makeToken('tag', '<tag>', startMark, endMark, { value: [handle, suffix] });
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected '!', but found '${ch}'`, this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    while (isAlphaNum(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (ch === '!') {
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNum(ch) || URI_CHARS.includes(ch)) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length !== 0) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (chunks.length === 0) {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected URI, but found '${ch}'`, this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    // Decode %XX sequences as UTF-8 bytes.
    const bytes = [];
    let mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      let k;
      for (k = 0; k < 2; k += 1) {
        const ch = this.peek(k);
        if (!(/[0-9a-fA-F]/).test(ch)) {
          throw new ScannerError(`while scanning a ${name}`, startMark,
            `expected URI escape sequence of 2 hexdecimal numbers, but found '${ch}'`,
            this.getMark());
        }
      }
      bytes.push(parseInt(this.prefix(2), 16));
      this.forward(2);
      mark = this.getMark();
    }
    try {
      return Buffer.from(bytes).toString('utf8');
    } catch {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        'expected URI escape sequence of 2 hexdecimal numbers', mark);
    }
  }

  // ------------------------------------------------------------------
  // Block scalars
  // ------------------------------------------------------------------

  scanBlockScalar(style) {
    const folded = (style === '>');
    const chunks = [];
    const startMark = this.getMark();

    // Scan the header.
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    // Determine the indentation level and go to the first non-empty line.
    let minIndent = this.indent + 1;
    if (minIndent < 1) {
      minIndent = 1;
    }
    let breaks;
    let endMark;
    let indent;
    if (increment == null) {
      const result = this.scanBlockScalarIndentation();
      breaks = result[0];
      const maxIndent = result[1];
      endMark = result[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const result = this.scanBlockScalarBreaks(indent);
      breaks = result[0];
      endMark = result[1];
    }
    let lineBreak = '';

    // Scan the inner part of the block scalar.
    while (this.column === indent && this.peek() !== '\0') {
      chunks.push(...breaks);
      const leadingNonSpace = this.peek() !== ' ' && this.peek() !== '\t';
      let length = 0;
      while (!isBreak(this.peek(length)) && this.peek(length) !== '\0') {
        length += 1;
      }
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const result = this.scanBlockScalarBreaks(indent);
      breaks = result[0];
      endMark = result[1];
      if (this.column === indent && this.peek() !== '\0') {
        // Folding rules are ambiguous; this matches PyYAML.
        if (folded && lineBreak === '\n' && leadingNonSpace &&
            this.peek() !== ' ' && this.peek() !== '\t') {
          if (breaks.length === 0) {
            chunks.push(' ');
          }
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    // Chomp the tail.
    if (chomping !== false) {
      chunks.push(lineBreak);
    }
    if (chomping === true) {
      chunks.push(...breaks);
    }

    return makeToken('scalar', '<scalar>', startMark, endMark,
      { value: chunks.join(''), plain: false, style });
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = (ch === '+');
      this.forward();
      ch = this.peek();
      if (ch >= '0' && ch <= '9') {
        increment = ch.charCodeAt(0) - 48;
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1..9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (ch >= '0' && ch <= '9') {
      increment = ch.charCodeAt(0) - 48;
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1..9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = (ch === '+');
        this.forward();
      }
    }
    ch = this.peek();
    if (!isBlankOrBreak(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found '${ch}'`,
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') {
      this.forward();
    }
    if (this.peek() === '#') {
      while (!isBreak(this.peek()) && this.peek() !== '\0') {
        this.forward();
      }
    }
    const ch = this.peek();
    if (!isBreak(ch) && ch !== '\0') {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected a comment or a line break, but found '${ch}'`, this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (this.peek() === ' ' || isBreak(this.peek())) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) {
          maxIndent = this.column;
        }
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') {
      this.forward();
    }
    while (isBreak(this.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') {
        this.forward();
      }
    }
    return [chunks, endMark];
  }

  // ------------------------------------------------------------------
  // Flow (quoted) scalars
  // ------------------------------------------------------------------

  scanFlowScalar(style) {
    const double = (style === '"');
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    while (this.peek() !== quote) {
      chunks.push(...this.scanFlowScalarSpaces(double, startMark));
      chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.forward();
    const endMark = this.getMark();
    return makeToken('scalar', '<scalar>', startMark, endMark,
      { value: chunks.join(''), plain: false, style });
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!'\'"\\\0 \t\r\n  '.includes(this.peek(length))) {
        length += 1;
      }
      if (length !== 0) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      const ch = this.peek();
      if (!double && ch === '\'' && this.peek(1) === '\'') {
        chunks.push('\'');
        this.forward(2);
      } else if ((double && ch === '\'') || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        const esc = this.peek();
        if (Object.prototype.hasOwnProperty.call(ESCAPE_REPLACEMENTS, esc)) {
          chunks.push(ESCAPE_REPLACEMENTS[esc]);
          this.forward();
        } else if (Object.prototype.hasOwnProperty.call(ESCAPE_CODES, esc)) {
          const length = ESCAPE_CODES[esc];
          this.forward();
          for (let k = 0; k < length; k += 1) {
            if (!(/[0-9a-fA-F]/).test(this.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar', startMark,
                `expected escape sequence of ${length} hexdecimal numbers, but found '${this.peek(k)}'`,
                this.getMark());
            }
          }
          const code = parseInt(this.prefix(length), 16);
          chunks.push(String.fromCodePoint(code));
          this.forward(length);
        } else if (isBreak(esc)) {
          this.scanLineBreak();
          chunks.push(...this.scanFlowScalarBreaks(double, startMark));
        } else {
          throw new ScannerError('while scanning a double-quoted scalar', startMark,
            `found unknown escape character '${esc}'`, this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ' || this.peek(length) === '\t') {
      length += 1;
    }
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    } else if (isBreak(ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') {
        chunks.push(lineBreak);
      } else if (breaks.length === 0) {
        chunks.push(' ');
      }
      chunks.push(...breaks);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      // Instead of checking indentation, check for document separators.
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') &&
          isBlankOrBreak(this.peek(3))) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (this.peek() === ' ' || this.peek() === '\t') {
        this.forward();
      }
      if (isBreak(this.peek())) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  // ------------------------------------------------------------------
  // Plain scalars
  // ------------------------------------------------------------------

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    // Note: zero indentation is allowed for scalars (handled naturally).
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') {
        break;
      }
      for (;;) {
        const ch = this.peek(length);
        if (BLANK_OR_BREAK.includes(ch) ||
            (ch === ':' &&
              (BLANK_OR_BREAK + (this.flowLevel !== 0 ? ',[]{}' : ''))
                .includes(this.peek(length + 1))) ||
            (this.flowLevel !== 0 && ',?[]{}'.includes(ch))) {
          break;
        }
        length += 1;
      }
      if (length === 0) {
        break;
      }
      this.allowSimpleKey = false;
      chunks.push(...spaces);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces.length === 0 || this.peek() === '#' ||
          (this.flowLevel === 0 && this.column < indent)) {
        break;
      }
    }
    return makeToken('scalar', '<scalar>', startMark, endMark,
      { value: chunks.join(''), plain: true, style: '' });
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') {
      length += 1;
    }
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (isBreak(ch)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') &&
          isBlankOrBreak(this.peek(3))) {
        return [];
      }
      const breaks = [];
      while (this.peek() === ' ' || isBreak(this.peek())) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') &&
              isBlankOrBreak(this.peek(3))) {
            return [];
          }
        }
      }
      if (lineBreak !== '\n') {
        chunks.push(lineBreak);
      } else if (breaks.length === 0) {
        chunks.push(' ');
      } else {
        chunks.push('\n');
      }
      chunks.push(...breaks);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }
}

