// Event parser: a port of PyYAML's parser.py. Consumes the token stream
// produced by Scanner and produces parse events using the same state
// machine, so grammar errors surface at the same points as PyYAML.

import { ParserError } from './errors.mjs';

const DEFAULT_TAGS = {
  '!': '!',
  '!!': 'tag:yaml.org,2002:',
};

function event(type, extra) {
  return Object.assign({ type }, extra);
}

export class Parser {
  constructor(scanner) {
    this.tokens = scanner.tokens;
    this.pos = 0;
    this.currentEvent = null;
    this.states = [];
    this.marks = [];
    this.state = () => this.parseStreamStart();
    this.yamlVersion = null;
    this.tagHandles = { ...DEFAULT_TAGS };
  }

  // ------------------------------------------------------------------
  // Token / event access
  // ------------------------------------------------------------------

  checkToken(...types) {
    const token = this.tokens[this.pos];
    if (!token) return false;
    if (types.length === 0) return true;
    return types.includes(token.type);
  }

  peekToken() {
    return this.tokens[this.pos];
  }

  getToken() {
    return this.tokens[this.pos++];
  }

  checkEvent(...types) {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state();
    }
    if (this.currentEvent !== null) {
      if (types.length === 0) return true;
      return types.includes(this.currentEvent.type);
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // ------------------------------------------------------------------
  // Grammar states
  // ------------------------------------------------------------------

  // stream ::= STREAM-START implicit_document? explicit_document* STREAM-END
  parseStreamStart() {
    const token = this.getToken();
    const ev = event('stream-start', { startMark: token.startMark, endMark: token.endMark });
    this.state = () => this.parseImplicitDocumentStart();
    return ev;
  }

  // implicit_document ::= block_node DOCUMENT-END*
  parseImplicitDocumentStart() {
    if (!this.checkToken('directive', 'document-start', 'stream-end')) {
      this.tagHandles = { ...DEFAULT_TAGS };
      const token = this.peekToken();
      const ev = event('document-start', {
        startMark: token.startMark, endMark: token.startMark,
        explicit: false, version: null, tags: null,
      });
      this.states.push(() => this.parseDocumentEnd());
      this.state = () => this.parseNode(true, false);
      return ev;
    }
    return this.parseDocumentStart();
  }

  // explicit_document ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
  parseDocumentStart() {
    // Parse any extra document end indicators.
    while (this.checkToken('document-end')) {
      this.getToken();
    }
    // Parse an explicit document.
    if (!this.checkToken('stream-end')) {
      const token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken('document-start')) {
        throw new ParserError(null, null,
          `expected '<document start>', but found '${this.peekToken().id}'`,
          this.peekToken().startMark);
      }
      const endToken = this.getToken();
      const ev = event('document-start', {
        startMark, endMark: endToken.endMark,
        explicit: true, version, tags,
      });
      this.states.push(() => this.parseDocumentEnd());
      this.state = () => this.parseDocumentContent();
      return ev;
    }
    // Parse the end of the stream.
    const token = this.getToken();
    const ev = event('stream-end', { startMark: token.startMark, endMark: token.endMark });
    this.states = [];
    this.marks = [];
    this.state = null;
    return ev;
  }

  parseDocumentContent() {
    if (this.checkToken('directive', 'document-start', 'document-end', 'stream-end')) {
      const token = this.peekToken();
      const ev = this.processEmptyScalar(token.endMark);
      this.state = this.states.pop();
      return ev;
    }
    return this.parseBlockNode();
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = startMark;
    let explicitEnd = false;
    if (this.checkToken('document-end')) {
      token = this.getToken();
      endMark = token.endMark;
      explicitEnd = true;
    }
    const ev = event('document-end', { startMark, endMark, explicit: explicitEnd });
    this.state = () => this.parseImplicitDocumentStart();
    return ev;
  }

  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  // node ::= ALIAS | properties content | content
  parseNode(block, indentlessSequence) {
    if (this.checkToken('alias')) {
      const token = this.getToken();
      const ev = event('alias', {
        anchor: token.value,
        startMark: token.startMark, endMark: token.endMark,
      });
      this.state = this.states.pop();
      return ev;
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken('anchor')) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken('tag')) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.checkToken('tag')) {
      let token = this.getToken();
      startMark = tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.checkToken('anchor')) {
        token = this.getToken();
        startMark = token.startMark;
        endMark = token.endMark;
        anchor = token.value;
      }
    }
    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!(handle in this.tagHandles)) {
          throw new ParserError('while parsing a node', startMark,
            `found undefined tag handle '${handle}'`, tagMark);
        }
        tag = this.tagHandles[handle] + suffix;
      } else {
        tag = suffix;
      }
    }
    if (startMark === null) {
      startMark = endMark = this.peekToken().startMark;
    }
    let implicit = (tag === null || tag === '!');
    if (indentlessSequence && this.checkToken('block-entry')) {
      endMark = this.peekToken().endMark;
      const ev = event('sequence-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: false,
      });
      this.state = () => this.parseIndentlessSequenceEntry();
      return ev;
    }
    if (this.checkToken('scalar')) {
      const token = this.getToken();
      endMark = token.endMark;
      if ((token.plain && tag === null) || tag === '!') {
        implicit = [true, false];
      } else if (tag === null) {
        implicit = [false, true];
      } else {
        implicit = [false, false];
      }
      const ev = event('scalar', {
        anchor, tag, implicit, value: token.value,
        startMark, endMark, style: token.style,
      });
      this.state = this.states.pop();
      return ev;
    }
    if (this.checkToken('flow-sequence-start')) {
      endMark = this.peekToken().endMark;
      const ev = event('sequence-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: true,
      });
      this.state = () => this.parseFlowSequenceFirstEntry();
      return ev;
    }
    if (this.checkToken('flow-mapping-start')) {
      endMark = this.peekToken().endMark;
      const ev = event('mapping-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: true,
      });
      this.state = () => this.parseFlowMappingFirstKey();
      return ev;
    }
    if (block && this.checkToken('block-sequence-start')) {
      endMark = this.peekToken().startMark;
      const ev = event('sequence-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: false,
      });
      this.state = () => this.parseBlockSequenceFirstEntry();
      return ev;
    }
    if (block && this.checkToken('block-mapping-start')) {
      endMark = this.peekToken().startMark;
      const ev = event('mapping-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: false,
      });
      this.state = () => this.parseBlockMappingFirstKey();
      return ev;
    }
    if (anchor !== null || tag !== null) {
      // Empty scalars are allowed even if an anchor or a tag is specified.
      const ev = event('scalar', {
        anchor, tag, implicit: [implicit, false], value: '',
        startMark, endMark, style: null,
      });
      this.state = this.states.pop();
      return ev;
    }
    const node = block ? 'block' : 'flow';
    const token = this.peekToken();
    throw new ParserError(`while parsing a ${node} node`, startMark,
      `expected the node content, but found '${token.id}'`, token.startMark);
  }

  // block_sequence ::= BLOCK-SEQUENCE-START (BLOCK-ENTRY block_node?)* BLOCK-END
  parseBlockSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.checkToken('block-entry')) {
      const token = this.getToken();
      if (!this.checkToken('block-entry', 'block-end')) {
        this.states.push(() => this.parseBlockSequenceEntry());
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = () => this.parseBlockSequenceEntry();
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('block-end')) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block collection',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found '${token.id}'`, token.startMark);
    }
    const token = this.getToken();
    const ev = event('sequence-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  // indentless_sequence ::= (BLOCK-ENTRY block_node?)+
  parseIndentlessSequenceEntry() {
    if (this.checkToken('block-entry')) {
      const token = this.getToken();
      if (!this.checkToken('block-entry', 'key', 'value', 'block-end')) {
        this.states.push(() => this.parseIndentlessSequenceEntry());
        return this.parseBlockNode();
      }
      this.state = () => this.parseIndentlessSequenceEntry();
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.peekToken();
    const ev = event('sequence-end', { startMark: token.startMark, endMark: token.startMark });
    this.state = this.states.pop();
    return ev;
  }

  // block_mapping ::= BLOCK-MAPPING_START ((KEY block_node_or_indentless_sequence?)
  //                   (VALUE block_node_or_indentless_sequence?)?)* BLOCK-END
  parseBlockMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.checkToken('key')) {
      const token = this.getToken();
      if (!this.checkToken('key', 'value', 'block-end')) {
        this.states.push(() => this.parseBlockMappingValue());
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = () => this.parseBlockMappingValue();
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('block-end')) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block mapping',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found '${token.id}'`, token.startMark);
    }
    const token = this.getToken();
    const ev = event('mapping-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  parseBlockMappingValue() {
    if (this.checkToken('value')) {
      const token = this.getToken();
      if (!this.checkToken('key', 'value', 'block-end')) {
        this.states.push(() => this.parseBlockMappingKey());
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = () => this.parseBlockMappingKey();
      return this.processEmptyScalar(token.endMark);
    }
    this.state = () => this.parseBlockMappingKey();
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  processEmptyScalar(mark) {
    return event('scalar', {
      anchor: null, tag: null, implicit: [true, false], value: '',
      startMark: mark, endMark: mark, style: null,
    });
  }

  // flow_sequence ::= FLOW-SEQUENCE-START (flow_sequence_entry FLOW-ENTRY)*
  //                   flow_sequence_entry? FLOW-SEQUENCE-END
  parseFlowSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first = false) {
    if (!first) {
      if (this.checkToken('flow-entry')) {
        this.getToken();
      } else {
        const token = this.peekToken();
        throw new ParserError('while parsing a flow sequence',
          this.marks[this.marks.length - 1],
          `expected ',' or ']', but got '${token.id}'`, token.startMark);
      }
    }
    if (this.checkToken('key')) {
      const token = this.peekToken();
      const ev = event('mapping-start', {
        anchor: null, tag: null, implicit: true,
        startMark: token.startMark, endMark: token.endMark, flowStyle: true,
      });
      this.state = () => this.parseFlowSequenceEntryMappingKey();
      return ev;
    }
    if (!this.checkToken('flow-sequence-end')) {
      this.states.push(() => this.parseFlowSequenceEntry());
      return this.parseFlowNode();
    }
    const token = this.getToken();
    const ev = event('sequence-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  parseFlowSequenceEntryMappingKey() {
    const token = this.getToken();
    if (!this.checkToken('value', 'flow-entry', 'flow-sequence-end')) {
      this.states.push(() => this.parseFlowSequenceEntryMappingValue());
      return this.parseFlowNode();
    }
    this.state = () => this.parseFlowSequenceEntryMappingValue();
    return this.processEmptyScalar(token.endMark);
  }

  parseFlowSequenceEntryMappingValue() {
    if (this.checkToken('value')) {
      const token = this.getToken();
      if (!this.checkToken('flow-entry', 'flow-sequence-end')) {
        this.states.push(() => this.parseFlowSequenceEntryMappingEnd());
        return this.parseFlowNode();
      }
      this.state = () => this.parseFlowSequenceEntryMappingEnd();
      return this.processEmptyScalar(token.endMark);
    }
    this.state = () => this.parseFlowSequenceEntryMappingEnd();
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  parseFlowSequenceEntryMappingEnd() {
    this.state = () => this.parseFlowSequenceEntry();
    const token = this.peekToken();
    return event('mapping-end', { startMark: token.startMark, endMark: token.startMark });
  }

  // flow_mapping ::= FLOW-MAPPING-START (flow_mapping_entry FLOW-ENTRY)*
  //                  flow_mapping_entry? FLOW-MAPPING-END
  parseFlowMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowMappingKey(true);
  }

  parseFlowMappingKey(first = false) {
    if (!first) {
      if (this.checkToken('flow-entry')) {
        this.getToken();
      } else {
        const token = this.peekToken();
        throw new ParserError('while parsing a flow mapping',
          this.marks[this.marks.length - 1],
          `expected ',' or '}', but got '${token.id}'`, token.startMark);
      }
    }
    if (this.checkToken('key')) {
      const token = this.getToken();
      if (!this.checkToken('value', 'flow-entry', 'flow-mapping-end')) {
        this.states.push(() => this.parseFlowMappingValue());
        return this.parseFlowNode();
      }
      this.state = () => this.parseFlowMappingValue();
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('flow-mapping-end')) {
      this.states.push(() => this.parseFlowMappingKey());
      return this.parseFlowNode();
    }
    const token = this.getToken();
    const ev = event('mapping-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  parseFlowMappingValue() {
    if (this.checkToken('value')) {
      const token = this.getToken();
      if (!this.checkToken('flow-entry', 'flow-mapping-end')) {
        this.states.push(() => this.parseFlowMappingKey());
        return this.parseFlowNode();
      }
      this.state = () => this.parseFlowMappingKey();
      return this.processEmptyScalar(token.endMark);
    }
    this.state = () => this.parseFlowMappingKey();
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  // ------------------------------------------------------------------
  // Directives
  // ------------------------------------------------------------------

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = {};
    while (this.checkToken('directive')) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null,
            'found duplicate YAML directive', token.startMark);
        }
        const [major, minor] = token.value;
        if (major !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (handle in this.tagHandles) {
          throw new ParserError(null, null,
            `duplicate tag handle '${handle}'`, token.startMark);
        }
        this.tagHandles[handle] = prefix;
      }
    }
    let value;
    if (Object.keys(this.tagHandles).length > 0) {
      value = [this.yamlVersion, { ...this.tagHandles }];
    } else {
      value = [this.yamlVersion, null];
    }
    for (const key of Object.keys(DEFAULT_TAGS)) {
      if (!(key in this.tagHandles)) {
        this.tagHandles[key] = DEFAULT_TAGS[key];
      }
    }
    return value;
  }
}

// Node composer: a port of PyYAML's composer.py. Builds the node graph
// (ScalarNode / SequenceNode / MappingNode) from parse events, handling
// anchors, aliases (shared node references) and duplicate-anchor errors.

import { ComposerError } from './errors.mjs';
import { resolve } from './resolver.mjs';

export class ScalarNode {
  constructor(tag, value, startMark, endMark, style) {
    this.kind = 'scalar';
    this.id = 'scalar';
    this.tag = tag;
    this.value = value;
    this.startMark = startMark;
    this.endMark = endMark;
    this.style = style;
  }
}

export class SequenceNode {
  constructor(tag, value, startMark, endMark, flowStyle) {
    this.kind = 'sequence';
    this.id = 'sequence';
    this.tag = tag;
    this.value = value;
    this.startMark = startMark;
    this.endMark = endMark;
    this.flowStyle = flowStyle;
  }
}

export class MappingNode {
  constructor(tag, value, startMark, endMark, flowStyle) {
    this.kind = 'mapping';
    this.id = 'mapping';
    this.tag = tag;
    this.value = value;
    this.startMark = startMark;
    this.endMark = endMark;
    this.flowStyle = flowStyle;
  }
}

export class Composer {
  constructor(parser) {
    this.parser = parser;
    this.anchors = new Map();
  }

  checkEvent(...types) { return this.parser.checkEvent(...types); }
  peekEvent() { return this.parser.peekEvent(); }
  getEvent() { return this.parser.getEvent(); }

  // Returns the single document's root node, or null for an empty stream.
  // Mirrors PyYAML's Composer.get_single_node + BaseConstructor.get_single_data.
  getSingleNode() {
    // Drop the STREAM-START event.
    this.getEvent();
    // Compose the root node of the first (and only) document.
    let node = null;
    if (!this.checkEvent('stream-end')) {
      node = this.composeDocument();
    }
    // Ensure that the stream contains a single document.
    if (!this.checkEvent('stream-end')) {
      const ev = this.getEvent();
      throw new ComposerError('expected a single document in the stream',
        node.startMark, 'but found another document', ev.startMark);
    }
    // Drop the STREAM-END event.
    this.getEvent();
    return node;
  }

  composeDocument() {
    // Drop the DOCUMENT-START event.
    this.getEvent();
    // Compose the root node.
    const node = this.composeNode(null, null);
    // Drop the DOCUMENT-END event.
    this.getEvent();
    this.anchors.clear();
    return node;
  }

  composeNode(parent, index) {
    if (this.checkEvent('alias')) {
      const ev = this.getEvent();
      const anchor = ev.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(null, null,
          `found undefined alias '${anchor}'`, ev.startMark);
      }
      return this.anchors.get(anchor);
    }
    const ev = this.peekEvent();
    const anchor = ev.anchor;
    if (anchor !== null && anchor !== undefined && this.anchors.has(anchor)) {
      throw new ComposerError(
        `found duplicate anchor '${anchor}'; first occurrence`,
        this.anchors.get(anchor).startMark, 'second occurrence', ev.startMark);
    }
    let node;
    if (this.checkEvent('scalar')) {
      node = this.composeScalarNode(anchor);
    } else if (this.checkEvent('sequence-start')) {
      node = this.composeSequenceNode(anchor);
    } else if (this.checkEvent('mapping-start')) {
      node = this.composeMappingNode(anchor);
    }
    return node;
  }

  composeScalarNode(anchor) {
    const ev = this.getEvent();
    let tag = ev.tag;
    if (tag === null || tag === '!') {
      tag = resolve('scalar', ev.value, ev.implicit);
    }
    const node = new ScalarNode(tag, ev.value, ev.startMark, ev.endMark, ev.style);
    if (anchor !== null && anchor !== undefined) {
      this.anchors.set(anchor, node);
    }
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = resolve('sequence', null, startEvent.implicit);
    }
    const node = new SequenceNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null && anchor !== undefined) {
      this.anchors.set(anchor, node);
    }
    let index = 0;
    while (!this.checkEvent('sequence-end')) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = resolve('mapping', null, startEvent.implicit);
    }
    const node = new MappingNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null && anchor !== undefined) {
      this.anchors.set(anchor, node);
    }
    while (!this.checkEvent('mapping-end')) {
      const itemKey = this.composeNode(node, node.value.length);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }
}

// Implicit tag resolver: a port of PyYAML's resolver.py default implicit
// resolvers (the YAML 1.1 core schema as PyYAML implements it).

export const STR_TAG = 'tag:yaml.org,2002:str';
export const SEQ_TAG = 'tag:yaml.org,2002:seq';
export const MAP_TAG = 'tag:yaml.org,2002:map';
export const NULL_TAG = 'tag:yaml.org,2002:null';
export const BOOL_TAG = 'tag:yaml.org,2002:bool';
export const INT_TAG = 'tag:yaml.org,2002:int';
export const FLOAT_TAG = 'tag:yaml.org,2002:float';
export const BINARY_TAG = 'tag:yaml.org,2002:binary';
export const TIMESTAMP_TAG = 'tag:yaml.org,2002:timestamp';
export const MERGE_TAG = 'tag:yaml.org,2002:merge';
export const VALUE_TAG = 'tag:yaml.org,2002:value';
export const YAML_TAG = 'tag:yaml.org,2002:yaml';
export const SET_TAG = 'tag:yaml.org,2002:set';
export const OMAP_TAG = 'tag:yaml.org,2002:omap';
export const PAIRS_TAG = 'tag:yaml.org,2002:pairs';

// first-char -> list of [tag, regexp], kept in PyYAML's registration order.
const implicitResolvers = new Map();

function addImplicitResolver(tag, re, first) {
  const chars = first == null ? [null] : first;
  for (const ch of chars) {
    if (!implicitResolvers.has(ch)) implicitResolvers.set(ch, []);
    implicitResolvers.get(ch).push([tag, re]);
  }
}

addImplicitResolver(BOOL_TAG,
  /^(?:yes|Yes|YES|no|No|NO|true|True|TRUE|false|False|FALSE|on|On|ON|off|Off|OFF)$/,
  [...'yYnNtTfFoO']);

addImplicitResolver(FLOAT_TAG,
  /^(?:[-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?|\.[0-9][0-9_]*(?:[eE][-+][0-9]+)?|[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*|[-+]?\.(?:inf|Inf|INF)|\.(?:nan|NaN|NAN))$/,
  [...'-+0123456789.']);

addImplicitResolver(INT_TAG,
  /^(?:[-+]?0b[0-1_]+|[-+]?0[0-7_]+|[-+]?(?:0|[1-9][0-9_]*)|[-+]?0x[0-9a-fA-F_]+|[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+)$/,
  [...'-+0123456789']);

addImplicitResolver(MERGE_TAG, /^(?:<<)$/, ['<']);

addImplicitResolver(NULL_TAG, /^(?:~|null|Null|NULL|)$/, ['~', 'n', 'N', '']);

addImplicitResolver(TIMESTAMP_TAG,
  /^(?:[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]|[0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?(?:[Tt]|[ \t]+)[0-9][0-9]?:[0-9][0-9]:[0-9][0-9](?:\.[0-9]*)?(?:[ \t]*(?:Z|[-+][0-9][0-9]?(?::[0-9][0-9])?))?)$/,
  [...'0123456789']);

addImplicitResolver(VALUE_TAG, /^(?:=)$/, ['=']);

// The following resolver is only for documentation purposes in PyYAML
// (plain scalars cannot start with '!', '&', or '*'); kept for parity.
addImplicitResolver(YAML_TAG, /^(?:!|&|\*)$/, [...'!&*']);

// kind: 'scalar' | 'sequence' | 'mapping'
// implicit: [implicitPlain, implicitQuoted] pair from the parser.
export function resolve(kind, value, implicit) {
  if (kind === 'scalar' && implicit[0]) {
    const first = value === '' ? '' : value[0];
    const resolvers = [
      ...(implicitResolvers.get(first) || []),
      ...(implicitResolvers.get(null) || []),
    ];
    for (const [tag, re] of resolvers) {
      if (re.test(value)) return tag;
    }
  }
  if (kind === 'scalar') return STR_TAG;
  if (kind === 'sequence') return SEQ_TAG;
  return MAP_TAG;
}

// Object constructor: a port of PyYAML's constructor.py (BaseConstructor +
// SafeConstructor). Builds the JavaScript values documented in types.mjs
// from the composed node graph. Two-phase (generator) construction is kept
// so that recursive anchor/alias structures work exactly like PyYAML.

import { Buffer } from 'node:buffer';
import { YFloat, YTimestamp } from './types.mjs';
import { ConstructorError } from './errors.mjs';
import {
  STR_TAG, SEQ_TAG, MAP_TAG, NULL_TAG, BOOL_TAG, INT_TAG, FLOAT_TAG,
  BINARY_TAG, TIMESTAMP_TAG, MERGE_TAG, VALUE_TAG, SET_TAG, OMAP_TAG,
  PAIRS_TAG,
} from './resolver.mjs';

// Decoded !!binary payload. Not part of the shared types.mjs model (which
// has no binary type), so the loader wraps it here; see the report.
export class YBinary {
  // data: a Buffer with the decoded bytes.
  constructor(data) {
    this.data = data;
  }
}

// Loose base64 decoding matching Python's base64.decodebytes (non-alphabet
// characters such as newlines are ignored).
function decodeBase64(text, node) {
  const cleaned = text.replace(/[^A-Za-z0-9+/=]/g, '');
  try {
    return Buffer.from(cleaned, 'base64');
  } catch {
    throw new ConstructorError(null, null,
      `failed to decode base64 data: ${cleaned}`, node.startMark);
  }
}

// Timestamp constructor regexp with named groups (PyYAML's
// SafeConstructor.timestamp_regexp).
const TIMESTAMP_RE = /^(?<year>[0-9][0-9][0-9][0-9])-(?<month>[0-9][0-9]?)-(?<day>[0-9][0-9]?)(?:(?:[Tt]|[ \t]+)(?<hour>[0-9][0-9]?):(?<minute>[0-9][0-9]):(?<second>[0-9][0-9])(?:\.(?<fraction>[0-9]*))?(?:[ \t]*(?<tz>Z|(?<tzSign>[-+])(?<tzHour>[0-9][0-9]?)(?::(?<tzMinute>[0-9][0-9]))?))?)?$/;

const BOOL_VALUES = {
  yes: true, no: false,
  true: true, false: false,
  on: true, off: false,
};

function isGenerator(obj) {
  return obj !== null && typeof obj === 'object' &&
    typeof obj.next === 'function' && typeof obj[Symbol.iterator] === 'function';
}

function pad2(n) {
  return String(n).padStart(2, '0');
}

// Days in a month, for validating timestamps like Python's datetime.
function daysInMonth(year, month) {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

export class SafeConstructor {
  constructor() {
    this.constructedObjects = new Map();
    this.recursiveObjects = new Set();
    this.stateGenerators = [];
    this.deepConstruct = false;

    this.yamlConstructors = new Map([
      [NULL_TAG, this.constructYamlNull],
      [BOOL_TAG, this.constructYamlBool],
      [INT_TAG, this.constructYamlInt],
      [FLOAT_TAG, this.constructYamlFloat],
      [BINARY_TAG, this.constructYamlBinary],
      [TIMESTAMP_TAG, this.constructYamlTimestamp],
      [OMAP_TAG, this.constructYamlOmap],
      [PAIRS_TAG, this.constructYamlPairs],
      [SET_TAG, this.constructYamlSet],
      [STR_TAG, this.constructYamlStr],
      [SEQ_TAG, this.constructYamlSeq],
      [MAP_TAG, this.constructYamlMap],
      [null, this.constructUndefined],
    ]);
  }

  // ------------------------------------------------------------------
  // BaseConstructor machinery
  // ------------------------------------------------------------------

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length > 0) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const gen of generators) {
        while (!gen.next().done) { /* exhaust */ }
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Set();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) {
      return this.constructedObjects.get(node);
    }
    let oldDeep;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null,
        'found unconstructable recursive node', node.startMark);
    }
    this.recursiveObjects.add(node);
    const ctor = this.yamlConstructors.has(node.tag)
      ? this.yamlConstructors.get(node.tag)
      : this.yamlConstructors.get(null);
    let data = ctor.call(this, node);
    if (isGenerator(data)) {
      const gen = data;
      data = gen.next().value;
      if (this.deepConstruct) {
        while (!gen.next().done) { /* exhaust */ }
      } else {
        this.stateGenerators.push(gen);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) {
      this.deepConstruct = oldDeep;
    }
    return data;
  }

  constructScalar(node) {
    if (node.kind === 'mapping') {
      // Special case: a mapping used as a scalar (YAML 'value' key idiom).
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === VALUE_TAG) {
          return this.constructScalar(valueNode);
        }
      }
    }
    if (node.kind !== 'scalar') {
      throw new ConstructorError(null, null,
        `expected a scalar node, but found ${node.kind}`, node.startMark);
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (node.kind !== 'sequence') {
      throw new ConstructorError(null, null,
        `expected a sequence node, but found ${node.kind}`, node.startMark);
    }
    return node.value.map((child) => this.constructObject(child, deep));
  }

  constructMapping(node, deep = false) {
    if (node.kind !== 'mapping') {
      throw new ConstructorError(null, null,
        `expected a mapping node, but found ${node.kind}`, node.startMark);
    }
    const mapping = {};
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, true);
      const skey = this.keyToString(key, node, keyNode);
      const value = this.constructObject(valueNode, deep);
      mapping[skey] = value;
    }
    return mapping;
  }

  // Mapping keys must become JS strings (types.mjs contract). Non-scalar
  // keys are unhashable in Python and raise like PyYAML does.
  keyToString(key, mapNode, keyNode) {
    if (typeof key === 'string') return key;
    if (key === null) return 'null';
    if (typeof key === 'boolean') return key ? 'true' : 'false';
    if (typeof key === 'number') return String(key);
    if (key instanceof YFloat) {
      const v = key.value;
      if (Number.isNaN(v)) return '.nan';
      if (v === Infinity) return '.inf';
      if (v === -Infinity) return '-.inf';
      if (Number.isInteger(v)) return v.toFixed(1);
      return String(v);
    }
    if (key instanceof YTimestamp) return key.text;
    throw new ConstructorError('while constructing a mapping',
      mapNode.startMark, 'found unhashable key', keyNode.startMark);
  }

  // Merge key ('<<') handling, port of SafeConstructor.flatten_mapping.
  flattenMapping(node) {
    const merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === MERGE_TAG) {
        node.value.splice(index, 1);
        if (valueNode.kind === 'mapping') {
          this.flattenMapping(valueNode);
          merge.push(...valueNode.value);
        } else if (valueNode.kind === 'sequence') {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (subnode.kind !== 'mapping') {
              throw new ConstructorError('while constructing a mapping',
                node.startMark,
                `expected a mapping for merging, but found ${subnode.kind}`,
                subnode.startMark);
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) {
            merge.push(...value);
          }
        } else {
          throw new ConstructorError('while constructing a mapping',
            node.startMark,
            `expected a mapping or list of mappings for merging, but found ${valueNode.kind}`,
            valueNode.startMark);
        }
      } else if (keyNode.tag === VALUE_TAG) {
        keyNode.tag = STR_TAG;
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length > 0) {
      node.value = merge.concat(node.value);
    }
  }

  // ------------------------------------------------------------------
  // SafeConstructor constructors
  // ------------------------------------------------------------------

  constructUndefined(node) {
    throw new ConstructorError(null, null,
      `could not determine a constructor for the tag '${node.tag}'`,
      node.startMark);
  }

  constructYamlNull() {
    return null;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    return BOOL_VALUES[value.toLowerCase()];
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node).replace(/_/g, '');
    let sign = 1;
    if (value[0] === '-') {
      sign = -1;
    }
    if (value[0] === '-' || value[0] === '+') {
      value = value.slice(1);
    }
    if (value === '0') {
      return 0;
    }
    if (value.startsWith('0b')) {
      return sign * parseInt(value.slice(2), 2);
    }
    if (value.startsWith('0x')) {
      return sign * parseInt(value.slice(2), 16);
    }
    if (value[0] === '0') {
      return sign * parseInt(value, 8);
    }
    if (value.includes(':')) {
      // Sexagesimal (base-60) integer.
      const digits = value.split(':').map((part) => parseInt(part, 10));
      digits.reverse();
      let base = 1;
      let result = 0;
      for (const digit of digits) {
        result += digit * base;
        base *= 60;
      }
      return sign * result;
    }
    return sign * parseInt(value, 10);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node).replace(/_/g, '').toLowerCase();
    let sign = 1;
    if (value[0] === '-') {
      sign = -1;
    }
    if (value[0] === '-' || value[0] === '+') {
      value = value.slice(1);
    }
    if (value === '.inf') {
      return new YFloat(sign * Infinity);
    }
    if (value === '.nan') {
      return new YFloat(NaN);
    }
    if (value.includes(':')) {
      // Sexagesimal (base-60) float.
      const digits = value.split(':').map((part) => parseFloat(part));
      digits.reverse();
      let base = 1;
      let result = 0.0;
      for (const digit of digits) {
        result += digit * base;
        base *= 60;
      }
      return new YFloat(sign * result);
    }
    return new YFloat(sign * parseFloat(value));
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    // PyYAML rejects non-ASCII content in binary scalars.
    // eslint-disable-next-line no-control-regex
    if (/[^\x00-\x7F]/.test(value)) {
      throw new ConstructorError(null, null,
        'invalid base64-encoded data in binary scalar', node.startMark);
    }
    return new YBinary(decodeBase64(value, node));
  }

  constructYamlTimestamp(node) {
    const match = TIMESTAMP_RE.exec(node.value);
    const g = match.groups;
    const year = parseInt(g.year, 10);
    const month = parseInt(g.month, 10);
    const day = parseInt(g.day, 10);
    if (g.hour === undefined) {
      // Plain date: validate like datetime.date does.
      if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
        throw new ConstructorError(null, null,
          `invalid date '${node.value}'`, node.startMark);
      }
      return new YTimestamp(
        `${String(year).padStart(4, '0')}-${pad2(month)}-${pad2(day)}`);
    }
    const hour = parseInt(g.hour, 10);
    const minute = parseInt(g.minute, 10);
    const second = parseInt(g.second, 10);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month) ||
        hour > 23 || minute > 59 || second > 59) {
      throw new ConstructorError(null, null,
        `invalid timestamp '${node.value}'`, node.startMark);
    }
    // Python's isoformat() emits microseconds (6 digits) only when nonzero;
    // the constructor zero-pads any fraction to 6 digits, so any fraction
    // present in the source produces a 6-digit fraction in the output.
    let fraction = '';
    if (g.fraction) {
      fraction = '.' + g.fraction.slice(0, 6).padEnd(6, '0');
    }
    let tz = '';
    if (g.tz === 'Z') {
      tz = '+00:00';
    } else if (g.tzSign) {
      const tzHour = parseInt(g.tzHour, 10);
      const tzMinute = g.tzMinute !== undefined ? parseInt(g.tzMinute, 10) : 0;
      if (tzHour > 23 || tzMinute > 59) {
        throw new ConstructorError(null, null,
          `invalid timestamp '${node.value}'`, node.startMark);
      }
      tz = `${g.tzSign}${pad2(tzHour)}:${pad2(tzMinute)}`;
    }
    const text = `${String(year).padStart(4, '0')}-${pad2(month)}-${pad2(day)}` +
      ` ${pad2(hour)}:${pad2(minute)}:${pad2(second)}${fraction}${tz}`;
    return new YTimestamp(text);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  *constructYamlSeq(node) {
    const data = [];
    yield data;
    data.push(...this.constructSequence(node));
  }

  *constructYamlMap(node) {
    const data = {};
    yield data;
    this.flattenMapping(node);
    Object.assign(data, this.constructMapping(node));
  }

  *constructYamlSet(node) {
    const data = {};
    yield data;
    Object.assign(data, this.constructMapping(node));
  }

  // Ordered maps and pairs: sequences of single-pair mappings. There is no
  // dedicated JS representation in the value model, so they become arrays
  // of single-key plain objects (matching the sequence-of-mappings shape).
  *constructYamlOmap(node) {
    const omap = [];
    yield omap;
    if (node.kind !== 'sequence') {
      throw new ConstructorError('while constructing an ordered map',
        node.startMark, `expected a sequence, but found ${node.kind}`,
        node.startMark);
    }
    for (const subnode of node.value) {
      if (subnode.kind !== 'mapping') {
        throw new ConstructorError('while constructing an ordered map',
          node.startMark,
          `expected a mapping of length 1, but found ${subnode.kind}`,
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing an ordered map',
          node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode);
      omap.push({ [this.keyToString(key, node, keyNode)]: this.constructObject(valueNode) });
    }
  }

  *constructYamlPairs(node) {
    const pairs = [];
    yield pairs;
    if (node.kind !== 'sequence') {
      throw new ConstructorError('while constructing pairs', node.startMark,
        `expected a sequence, but found ${node.kind}`, node.startMark);
    }
    for (const subnode of node.value) {
      if (subnode.kind !== 'mapping') {
        throw new ConstructorError('while constructing pairs', node.startMark,
          `expected a mapping of length 1, but found ${subnode.kind}`,
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing pairs', node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode);
      pairs.push({ [this.keyToString(key, node, keyNode)]: this.constructObject(valueNode) });
    }
  }
}

// YAML 1.1 safe loader: the equivalent of PyYAML's yaml.safe_load().
//
// Pipeline: Scanner (tokens) -> Parser (events) -> Composer (node graph)
// -> SafeConstructor (JavaScript values per the types.mjs value model).

import { Scanner } from './scanner.mjs';
import { Parser } from './parser.mjs';
import { Composer } from './composer.mjs';
import { SafeConstructor, YBinary } from './constructor.mjs';

// Parses the given YAML text and returns the constructed value.
// Returns null for an empty stream. Throws a YAMLError subclass for any
// invalid input, mirroring PyYAML's safe_load failures.
export function safeLoad(text) {
  const scanner = new Scanner(text);
  const parser = new Parser(scanner);
  const composer = new Composer(parser);
  const node = composer.getSingleNode();
  if (node === null) {
    return null;
  }
  const constructor = new SafeConstructor();
  return constructor.constructDocument(node);
}

export { YBinary };
export { YFloat, YTimestamp } from './types.mjs';
export { YAMLError } from './errors.mjs';

args.command:
cat > /tmp/harness.mjs <<'EOF'
import { safeLoad, YBinary, YFloat, YTimestamp } from '/output/yaml/loader.mjs';

function floatRepr(v) {
  if (Number.isNaN(v)) return '.nan';
  if (v === Infinity) return '.inf';
  if (v === -Infinity) return '-.inf';
  if (Number.isInteger(v) && Math.abs(v) < 1e16) return v.toFixed(1);
  return String(v);
}

// Canonical serialization of the loaded value for comparison.
function canon(v) {
  if (v === null) return 'null';
  if (typeof v === 'boolean') return 'bool:' + v;
  if (typeof v === 'number') return 'int:' + v;
  if (typeof v === 'string') return 'str:' + JSON.stringify(v);
  if (v instanceof YFloat) return 'float:' + floatRepr(v.value);
  if (v instanceof YTimestamp) return 'ts:' + v.text;
  if (v instanceof YBinary) return 'bin:' + v.data.toString('base64');
  if (Array.isArray(v)) return '[' + v.map(canon).join(', ') + ']';
  if (typeof v === 'object') {
    const keys = Object.keys(v).sort();
    return '{' + keys.map(k => JSON.stringify(k) + '=' + canon(v[k])).join(', ') + '}';
  }
  return '???' + typeof v;
}

let pass = 0, fail = 0;
function ok(input, expected) {
  let got;
  try {
    got = canon(safeLoad(input));
  } catch (e) {
    got = 'ERROR:' + e.name + ': ' + e.message.split('\n')[0];
  }
  if (got === expected) { pass++; }
  else { fail++; console.log('FAIL', JSON.stringify(input)); console.log('  expected:', expected); console.log('  got:     ', got); }
}
function err(input, frag) {
  try {
    const v = safeLoad(input);
    fail++; console.log('FAIL(no-throw)', JSON.stringify(input), '->', canon(v), 'wanted error:', frag);
  } catch (e) {
    if (e.message.includes(frag)) pass++;
    else { fail++; console.log('FAIL(errmsg)', JSON.stringify(input)); console.log('  got:', e.message.split('\n').slice(0,3).join(' | ')); console.log('  wanted fragment:', frag); }
  }
}

